<?php if(!defined('APP_ENTRY'))exit; $role=$user['role']; $uid=(int)$user['id']; if($role==='admin'){ $cards=['Students'=>one('SELECT COUNT(*) n FROM students')['n'],'Classes'=>one('SELECT COUNT(*) n FROM classes')['n'],'Teachers'=>one("SELECT COUNT(*) n FROM staff_accounts WHERE role='teacher'")['n'],'Courses'=>one('SELECT COUNT(*) n FROM courses')['n']]; } elseif($role==='teacher'){ $cards=['Assigned classes'=>one('SELECT COUNT(*) n FROM classes WHERE teacher_id=?',[$uid])['n'],'Students in your classes'=>one('SELECT COUNT(DISTINCT e.student_id) n FROM enrollments e JOIN classes c ON c.id=e.class_id WHERE c.teacher_id=?',[$uid])['n'],'Grades recorded'=>one('SELECT COUNT(*) n FROM grades g JOIN enrollments e ON e.id=g.enrollment_id JOIN classes c ON c.id=e.class_id WHERE c.teacher_id=?',[$uid])['n']]; } else { $sid=$user['student_id']; $cards=['Enrolled classes'=>one('SELECT COUNT(*) n FROM enrollments WHERE student_id=?',[$sid])['n'],'Recorded grades'=>one('SELECT COUNT(*) n FROM grades g JOIN enrollments e ON e.id=g.enrollment_id WHERE e.student_id=?',[$sid])['n'],'Average score'=>one('SELECT ROUND(AVG(g.score),2) n FROM grades g JOIN enrollments e ON e.id=g.enrollment_id WHERE e.student_id=?',[$sid])['n']??'—']; } ?>
<p class="muted">Welcome, <?=e($user['name'])?>. <?=e(['admin'=>'Manage academic records and account access.','teacher'=>'Manage grades for your assigned classes.','student'=>'View your own academic information.'][$role])?></p><div class="stats"><?php foreach($cards as $label=>$count):?><div class="stat"><span><?=e($label)?></span><strong><?=e($count)?></strong></div><?php endforeach;?></div><section class="panel"><h2>Your workspace</h2><p class="muted">Choose a module from the navigation. Access is checked on the server for every request.</p><div class="toolbar"><a class="button" href="<?=e(url('classes'))?>">View classes</a><a class="button secondary" href="<?=e(url('grades'))?>">View grades</a></div></section>
